fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Requires: The `start` index must be within bounds such that the subarray can fit in the main array.
    // Ensures: Returns true if the subarray matches the main array starting at index `start`, false otherwise.
    // Requires: `main.len() >= start + sub.len()`
    // Ensures: `result == (main[start..start + sub.len()] == sub[..])`
    // Invariant: `0 <= start && start <= main.len()`
    // Decreases: `main.len() - start`
    
    assert!(start <= main.len()); // Ensure start is within bounds
    if start + sub.len() > main.len() {
        return false;
    }
    
    // Check if the elements match
    for j in 0..sub.len() {
        assert!(j < sub.len()); // Ensure j is within bounds of sub
        if main[start + j] != sub[j] {
            return false;
        }
    }
    
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Requires: The lengths of the main and sub arrays must be non-negative.
    // Ensures: Returns true if `sub` is a subarray of `main`, false otherwise.
    // Requires: `sub.len() <= main.len()`
    // Ensures: `result == (exists k: usize, 0 <= k && k <= main.len() - sub.len() && check_match_at(main, sub, k))`
    // Invariant: `0 <= k && k <= main.len() - sub.len()`
    // Decreases: `main.len() - sub.len()`
    
    assert!(main.len() >= 0 && sub.len() >= 0); // Ensure lengths are non-negative
    if sub.is_empty() {
        return true;
    }
    
    if sub.len() > main.len() {
        return false;
    }
    
    // Check each possible starting index in the main array
    for k in 0..=main.len() - sub.len() {
        assert!(k <= main.len() - sub.len()); // Ensure k is within bounds
        if check_match_at(main, sub, k) {
            return true;
        }
    }
    
    false
}

